'use strict';
const catalog=[['Orange','#f36b21'],['Navy','#243346'],['Purple','#8760ed'],['Pink','#ed65c7'],['Red','#e32737'],['Blue','#3434cb'],['Yellow','#f2e62c'],['Green','#398177'],['Brown','#9b603b'],['White','#edf3f2'],['Clear','#c9d8dc'],['Taupe','#ad9390']].map(([name,hex])=>({name,hex}));
let selected=0,quantity=1,cart=[];
try{const saved=JSON.parse(localStorage.getItem('clickitpickit-bag')||'[]');if(Array.isArray(saved))cart=saved.filter(x=>Number.isInteger(x.color)&&catalog[x.color]&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=20)}catch{}
const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
function update(){ $('quantity').textContent=quantity;$('addToBag').innerHTML=`Add to bag — ${money(quantity*15)} <span>+</span>`;$('bagCount').textContent=cart.reduce((a,b)=>a+b.quantity,0);try{localStorage.setItem('clickitpickit-bag',JSON.stringify(cart))}catch{}}
function choose(i){selected=i;$('colorName').textContent=catalog[i].name;document.querySelectorAll('.swatches button').forEach((b,j)=>{b.classList.toggle('selected',i===j);b.setAttribute('aria-pressed',i===j)});if(window.setKnifeColor)window.setKnifeColor(catalog[i].hex);}
function renderCatalog(){ $('swatches').replaceChildren();catalog.forEach((c,i)=>{const b=document.createElement('button');b.style.background=c.hex;b.type='button';b.setAttribute('aria-label',c.name);b.onclick=()=>choose(i);$('swatches').append(b)});choose(selected)}
$('minus').onclick=()=>{quantity=Math.max(1,quantity-1);update()};$('plus').onclick=()=>{quantity=Math.min(20,quantity+1);update()};let toastTimer;
$('addToBag').onclick=()=>{const item=cart.find(x=>x.color===selected);if(item)item.quantity=Math.min(20,item.quantity+quantity);else cart.push({color:selected,quantity});update();$('toast').textContent=`${catalog[selected].name} Pocket Click added to your bag`;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)};
function drawCart(){const list=$('cartItems');list.replaceChildren();if(!cart.length){list.innerHTML='<p>Your next little adventure is waiting. Pick a color to get started.</p>';$('cartBottom').innerHTML='<button class="button navy" id="continueShopping">Explore the pocket tool ↗</button>';$('continueShopping').onclick=()=>{$('cartDialog').close();location.hash='shop'};return}cart.forEach((item,i)=>{const line=document.createElement('div');line.className='cart-line';line.innerHTML=`<div><strong>Pocket Click · ${catalog[item.color].name}</strong><span class="small">${money(15)} each · Quantity ${item.quantity}</span><button data-remove="${i}">Remove</button></div><b>${money(item.quantity*15)}</b>`;line.querySelector('button').onclick=()=>{cart.splice(i,1);update();drawCart()};list.append(line)});$('cartBottom').innerHTML=`<div class="cart-total"><span>Subtotal</span><span>${money(cart.reduce((a,b)=>a+b.quantity*15,0))}</span></div><div class="shipping-line"><span>Flat-rate shipping</span><span>$4.99</span></div><div class="cart-total"><span>Total before tax</span><span>${money(cart.reduce((a,b)=>a+b.quantity*15,0)+4.99)}</span></div><p class="small">Any applicable tax will be confirmed before payment.</p><div class="checkout-note"><strong>We're getting ready to open!</strong><p>Checkout is not available yet. Your picks stay in this browser, but no order has been placed and no payment has been taken.</p></div>`}
$('bagButton').onclick=()=>{drawCart();$('cartDialog').showModal()};$('closeCart').onclick=()=>$('cartDialog').close();$('cartDialog').addEventListener('click',e=>{if(e.target===$('cartDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('year').textContent=new Date().getFullYear();renderCatalog();update();

const gallery=[['open.jpg','Orange pocket tool open on a wooden table'],['closed.jpg','Orange pocket tool folded closed'],['colors.jpg','A selection of colorful printed pocket tools'],['lineup.jpg','Pocket tool colors lined up'],['size-inches.jpg','Orange pocket tool beside an inch-marked tape measure']];
function showPhoto(i){$('productPhoto').src='assets/'+gallery[i][0];$('productPhoto').alt=gallery[i][1];document.querySelectorAll('.thumbnails button').forEach((b,j)=>{b.classList.toggle('active',j===i);b.setAttribute('aria-pressed',String(j===i))})}
gallery.forEach(([src,alt],i)=>{const b=document.createElement('button');b.setAttribute('aria-label','View '+alt.toLowerCase());const img=document.createElement('img');img.src='assets/'+src;img.alt='';img.loading='lazy';b.append(img);b.onclick=()=>showPhoto(i);$('thumbnails').append(b)});showPhoto(0);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_shopping_bag',description:'Read the local shopping bag. No order or payment has been placed.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({items:cart.map(x=>({color:catalog[x.color].name,quantity:x.quantity})),subtotal:cart.reduce((n,x)=>n+x.quantity*15,0),shipping:cart.length?4.99:0,totalBeforeTax:cart.reduce((n,x)=>n+x.quantity*15,0)+(cart.length?4.99:0),currency:'USD',checkoutAvailable:false})},{name:'stage_pocket_tool',description:'Add a color and quantity to the local bag only. This does not place an order or take payment.',inputSchema:{type:'object',properties:{color:{type:'string',enum:catalog.map(x=>x.name)},quantity:{type:'integer',minimum:1,maximum:20}},required:['color','quantity'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const i=catalog.findIndex(c=>c.name===input?.color);if(i<0||!Number.isInteger(input.quantity)||input.quantity<1||input.quantity>20)throw new Error('Choose a listed color and a quantity from 1 to 20.');choose(i);quantity=input.quantity;update();$('addToBag').click();return {staged:true,orderPlaced:false,color:input.color,quantity:cart.find(x=>x.color===i).quantity}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
